// Python's `difflib.SequenceMatcher.ratio` and `difflib.get_close_matches`, over strings, for the lookup's near
// misses. Translated from CPython's `Lib/difflib.py`, whose algorithm its documentation calls "a little fancier
// than" Ratcliff and Obershelp's gestalt pattern matching (https://en.wikipedia.org/wiki/Gestalt_pattern_matching),
// and held to cases generated by Python's own `difflib`.
//
// The sequences are strings taken as code points, as Python takes them.

import { codePoints, compareCodePoints } from "./pystr.ts";

/** `(i, j, size)`: `a[i:i+size]` equals `b[j:j+size]`. */
type Block = readonly [number, number, number];

function calculateRatio(matches: number, length: number): number {
  return length ? (2.0 * matches) / length : 1.0;
}

/** Python's `difflib.SequenceMatcher(isjunk, a, b, autojunk)`, for its matching blocks and ratios.
 *
 * `isjunk`: whether an element of `b` is junk, which a match may not start with; `null` for none.
 * `autojunk`: whether, in a `b` of 200 elements or more, an element making up more than 1% of it is treated as
 *             junk too ("popular").
 */
export class SequenceMatcher {
  private a: string[] = [];
  private b: string[] = [];
  // For each element of `b`, its indices in `b`, ascending; the junk and popular elements left out.
  private b2j = new Map<string, number[]>();
  private bjunk = new Set<string>();
  private readonly isjunk: ((element: string) => boolean) | null;
  private readonly autojunk: boolean;
  private maybeFullBCount: Map<string, number> | null = null;
  private maybeMatchingBlocks: Block[] | null = null;

  constructor(isjunk: ((element: string) => boolean) | null = null, a = "", b = "", autojunk = true) {
    this.isjunk = isjunk;
    this.autojunk = autojunk;
    this.setSeq1(a);
    this.setSeq2(b);
  }

  setSeq1(a: string): void {
    this.a = codePoints(a);
    this.maybeMatchingBlocks = null;
  }

  setSeq2(b: string): void {
    this.b = codePoints(b);
    this.maybeMatchingBlocks = null;
    this.maybeFullBCount = null;
    this.chainB();
  }

  private chainB(): void {
    this.b2j = new Map();
    this.b.forEach((element, i) => {
      const indices = this.b2j.get(element);
      if (indices) {
        indices.push(i);
      } else {
        this.b2j.set(element, [i]);
      }
    });
    this.bjunk = new Set();
    if (this.isjunk) {
      for (const element of this.b2j.keys()) {
        if (this.isjunk(element)) {
          this.bjunk.add(element);
        }
      }
      for (const element of this.bjunk) {
        this.b2j.delete(element);
      }
    }
    // The "autojunk" heuristic: in a long `b`, an element making up more than 1% of it is left out of `b2j`.
    const n = this.b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [element, indices] of [...this.b2j]) {
        if (indices.length > ntest) {
          this.b2j.delete(element);
        }
      }
    }
  }

  /** The longest matching block in `a[alo:ahi]` and `b[blo:bhi]`, the earliest in `a` of the longest, and of those
   * the earliest in `b`. */
  findLongestMatch(alo: number, ahi: number, blo: number, bhi: number): Block {
    const { a, b, b2j, bjunk } = this;
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;
    // During an iteration of the loop, `j2len.get(j)` is the length of the longest match ending with `a[i-1]` and
    // `b[j]`.
    let j2len = new Map<number, number>();
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map<number, number>();
      for (const j of b2j.get(a[i]!) ?? []) {
        if (j < blo) {
          continue;
        }
        if (j >= bhi) {
          break;
        }
        const k = (j2len.get(j - 1) ?? 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }
    // Extend the best by equal non-junk elements on each end: the popular ones, which `b2j` leaves out.
    while (besti > alo && bestj > blo && !bjunk.has(b[bestj - 1]!) && a[besti - 1] === b[bestj - 1]) {
      besti--;
      bestj--;
      bestsize++;
    }
    while (besti + bestsize < ahi && bestj + bestsize < bhi && !bjunk.has(b[bestj + bestsize]!) &&
           a[besti + bestsize] === b[bestj + bestsize]) {
      bestsize++;
    }
    // Then by equal junk on each end, which no match may start with but which may as well join one.
    while (besti > alo && bestj > blo && bjunk.has(b[bestj - 1]!) && a[besti - 1] === b[bestj - 1]) {
      besti--;
      bestj--;
      bestsize++;
    }
    while (besti + bestsize < ahi && bestj + bestsize < bhi && bjunk.has(b[bestj + bestsize]!) &&
           a[besti + bestsize] === b[bestj + bestsize]) {
      bestsize++;
    }
    return [besti, bestj, bestsize];
  }

  /** The matching blocks, ascending and with adjacent ones merged, ending in the sentinel `(len(a), len(b), 0)`. */
  getMatchingBlocks(): Block[] {
    if (this.maybeMatchingBlocks !== null) {
      return this.maybeMatchingBlocks;
    }
    const la = this.a.length;
    const lb = this.b.length;
    const queue: [number, number, number, number][] = [[0, la, 0, lb]];
    const found: Block[] = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop()!;
      const block = this.findLongestMatch(alo, ahi, blo, bhi);
      const [i, j, k] = block;
      if (k) {
        found.push(block);
        if (alo < i && blo < j) {
          queue.push([alo, i, blo, j]);
        }
        if (i + k < ahi && j + k < bhi) {
          queue.push([i + k, ahi, j + k, bhi]);
        }
      }
    }
    found.sort((x, y) => x[0] - y[0] || x[1] - y[1] || x[2] - y[2]);
    const merged: Block[] = [];
    let [i1, j1, k1] = [0, 0, 0];
    for (const [i2, j2, k2] of found) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
        k1 += k2;
      } else {
        if (k1) {
          merged.push([i1, j1, k1]);
        }
        [i1, j1, k1] = [i2, j2, k2];
      }
    }
    if (k1) {
      merged.push([i1, j1, k1]);
    }
    merged.push([la, lb, 0]);
    this.maybeMatchingBlocks = merged;
    return merged;
  }

  /** How alike the two sequences are, from 0 to 1: twice the matched elements over all of them. */
  ratio(): number {
    const matches = this.getMatchingBlocks().reduce((sum, [, , k]) => sum + k, 0);
    return calculateRatio(matches, this.a.length + this.b.length);
  }

  /** An upper bound on `ratio`, from the elements alone, in any order. */
  quickRatio(): number {
    if (this.maybeFullBCount === null) {
      this.maybeFullBCount = new Map();
      for (const element of this.b) {
        this.maybeFullBCount.set(element, (this.maybeFullBCount.get(element) ?? 0) + 1);
      }
    }
    const fullBCount = this.maybeFullBCount;
    const avail = new Map<string, number>();
    let matches = 0;
    for (const element of this.a) {
      const numb = avail.has(element) ? avail.get(element)! : (fullBCount.get(element) ?? 0);
      avail.set(element, numb - 1);
      if (numb > 0) {
        matches++;
      }
    }
    return calculateRatio(matches, this.a.length + this.b.length);
  }

  /** An upper bound on `ratio`, from the lengths alone. */
  realQuickRatio(): number {
    const la = this.a.length;
    const lb = this.b.length;
    return calculateRatio(Math.min(la, lb), la + lb);
  }
}

/** Python's `difflib.get_close_matches(word, possibilities, n, cutoff)`: the `n` best of `possibilities` scoring
 * at least `cutoff` against `word`, best first. Equal scores come in reverse order of the strings, as Python's
 * comparison of `(score, string)` pairs puts them. */
export function getCloseMatches(word: string, possibilities: Iterable<string>, n = 3, cutoff = 0.6): string[] {
  if (!(n > 0)) {
    throw new RangeError(`n must be > 0: ${n}`);
  }
  if (!(cutoff >= 0.0 && cutoff <= 1.0)) {
    throw new RangeError(`cutoff must be in [0.0, 1.0]: ${cutoff}`);
  }
  const scored: [number, string][] = [];
  const matcher = new SequenceMatcher();
  matcher.setSeq2(word);
  for (const x of possibilities) {
    matcher.setSeq1(x);
    if (matcher.realQuickRatio() >= cutoff && matcher.quickRatio() >= cutoff && matcher.ratio() >= cutoff) {
      scored.push([matcher.ratio(), x]);
    }
  }
  scored.sort((p, q) => q[0] - p[0] || compareCodePoints(q[1], p[1]));
  return scored.slice(0, n).map(([, x]) => x);
}
